const fs = require('fs');
const SRC_CSV = '/data_sources/data.csv';
if (!fs.existsSync(SRC_CSV)) throw new Error('[WF-01] Introuvable : ' + SRC_CSV);
const csvBuf = fs.readFileSync(SRC_CSV);
console.log('[WF-01] data.csv lu : ' + csvBuf.length + ' octets');
return [{
  json: { fileName: 'data.csv', fileSize: csvBuf.length },
  binary: { data: { data: csvBuf.toString('base64'), mimeType: 'text/csv', fileName: 'data.csv' } }
}];

const crypto = require('crypto');
const fs = require('fs');

const SRC_JSON = '/data_sources/data.json';
if (!fs.existsSync(SRC_JSON)) throw new Error('[WF-01] Introuvable : ' + SRC_JSON);

const csvItem = $input.first();
const csvBuf  = Buffer.from(csvItem.binary.data.data, 'base64');

function parseCsvRobust(raw) {
  const text = raw.toString('utf8');
  const rows = []; let pos = 0, headers = null;
  function parseField() {
    if (text[pos] === '"') {
      pos++; let val = '';
      while (pos < text.length) {
        if (text[pos] === '"' && text[pos+1] === '"') { val += '"'; pos += 2; }
        else if (text[pos] === '"') { pos++; break; }
        else { val += text[pos++]; }
      }
      return val;
    }
    let val = '';
    while (pos < text.length && text[pos] !== ',' && text[pos] !== '\n' && text[pos] !== '\r') val += text[pos++];
    return val.trim();
  }
  function parseLine() {
    const fields = [];
    while (pos < text.length && text[pos] !== '\n' && text[pos] !== '\r') {
      fields.push(parseField());
      if (pos < text.length && text[pos] === ',') pos++;
    }
    while (pos < text.length && (text[pos] === '\n' || text[pos] === '\r')) pos++;
    return fields;
  }
  headers = parseLine();
  while (pos < text.length) {
    const fields = parseLine();
    if (fields.length === headers.length && fields.some(f => f !== '')) {
      const obj = {}; headers.forEach((h, i) => { obj[h] = fields[i] || ''; }); rows.push(obj);
    }
  }
  return rows;
}

const csvRows  = parseCsvRobust(csvBuf);
const jsonRows = JSON.parse(fs.readFileSync(SRC_JSON, 'utf8'));
const merged   = [...jsonRows, ...csvRows];
const mergedBuf = Buffer.from(JSON.stringify(merged), 'utf8');
const currentHash = crypto.createHash('md5').update(mergedBuf).digest('hex');

fs.mkdirSync('/staging/flat_files', { recursive: true });
fs.writeFileSync('/staging/flat_files/data_merged.json', mergedBuf);

console.log('[WF-01] data.json : ' + jsonRows.length + ' | data.csv : ' + csvRows.length + ' | total : ' + merged.length + ' | hash : ' + currentHash.slice(0,8) + '…');

return [{
  json: { fileName: 'data_merged.json', fileSize: mergedBuf.length,
          csvRows: csvRows.length, jsonRows: jsonRows.length, total: merged.length,
          currentHash, latestKey: 'flat_files/data_merged.json' },
  binary: { data: { data: mergedBuf.toString('base64'), mimeType: 'application/json', fileName: 'data_merged.json' } }
}];

const fs = require('fs');
function readChecksum(key) {
  const file = '/staging/_metadata/checksums/' + key + '.json';
  try { return JSON.parse(fs.readFileSync(file, 'utf8')); } catch(e) { return { hash: null }; }
}
const item = $input.first().json;
const currentHash = item.currentHash;
const { hash: storedHash } = readChecksum('data_merged');
const hashChanged = currentHash !== storedHash;
console.log('[CDC] hash=' + currentHash.slice(0,8) + '… changé=' + hashChanged);
return [{
  json: { currentHash, storedHash, hashChanged, latestKey: item.latestKey,
          csvRows: item.csvRows, jsonRows: item.jsonRows, total: item.total },
  binary: $input.first().binary
}];

const fs  = require('fs');
const cdc = $('CDC — Hash data_merged').first().json;
const dir = '/staging/_metadata/checksums';
fs.mkdirSync(dir, { recursive: true });
fs.writeFileSync(dir + '/data_merged.json',
  JSON.stringify({ hash: cdc.currentHash, updatedAt: new Date().toISOString() }, null, 2));
console.log('[WF-01] ✅ Checksum sauvegardé — ' + cdc.total + ' lignes (CSV:' + cdc.csvRows + ' + JSON:' + cdc.jsonRows + ')');
return [{ json: { status: 'success', file: 'data_merged.json', total: cdc.total } }];
